      { s: '감정 → ___', v: 's□□□□□□□□', mask: 's□□□□□□□□', a: ['sentiment'], ex: '정답 ▶ sentiment (감정)' },
      { s: '좌절감 → ___', v: 'f□□□□□□□□□□', mask: 'f□□□□□□□□□□', a: ['frustration'], ex: '정답 ▶ frustration (좌절감)' },
      { s: '불충분한 → ___', v: 'i□□□□□□□□□', mask: 'i□□□□□□□□□', a: ['inadequate'], ex: '정답 ▶ inadequate (불충분한)' },
      { s: '반대로 → ___', v: 'c□□□□□□□□□', mask: 'c□□□□□□□□□', a: ['conversely'], ex: '정답 ▶ conversely (반대로)' },
      { s: '강화하다 → ___', v: 'r□□□□□□□□', mask: 'r□□□□□□□□', a: ['reinforce'], ex: '정답 ▶ reinforce (강화하다)' },
      { s: '재현하다, 복제하다 → ___', v: 'r□□□□□□□□', mask: 'r□□□□□□□□', a: ['replicate'], ex: '정답 ▶ replicate (재현하다, 복제하다)' }
